<?php
namespace App\Livewire\Permissions;
use App\Models\User; use App\Models\UserPermissionOverride; use App\Support\PermissionRegistry; use Livewire\Component;
class Index extends Component { public ?int $userId=null; public array $values=[]; public function selectUser(?int $id):void{$this->userId=$id;$this->values=[];if(!$id)return;$u=User::findOrFail($id);foreach(PermissionRegistry::ALL as $p){$override=$u->permissionOverrides()->where('permission',$p)->first();$this->values[$p]=$override?($override->allowed?'allow':'deny'):'default';}} public function save():void{$this->authorize('company-admin');$u=User::findOrFail($this->userId);abort_if($u->role==='company_admin',422,'Company administrators always have all permissions.');foreach(PermissionRegistry::ALL as $p){$v=$this->values[$p]??'default';if($v==='default'){UserPermissionOverride::where('user_id',$u->id)->where('permission',$p)->delete();continue;}UserPermissionOverride::updateOrCreate(['user_id'=>$u->id,'permission'=>$p],['allowed'=>$v==='allow','updated_by'=>auth()->id()]);}session()->flash('success','Permissions saved.');} public function render(){return view('livewire.permissions.index',['users'=>User::where('role','hr')->orderBy('name')->get(),'permissions'=>PermissionRegistry::labels()]);} }
